() => {
  const headings = Array.from(document.querySelectorAll('h3'));
  const target = headings.find(h => h.textContent.includes('明细数据集'));
  if (target) {
    target.scrollIntoView({block: 'start', behavior: 'instant'});
    return 'scrolled to: ' + target.textContent;
  }
  return 'not found';
}

() => {
  const ta = document.querySelector('textarea, input[type="text"]');
  if (ta) {
    ta.scrollIntoView({block: 'end', behavior: 'instant'});
    return 'scrolled, value=' + ta.value;
  }
  return 'not found';
}

() => {
  const els = Array.from(document.querySelectorAll('textarea, input'));
  return els.map(e => ({tag: e.tagName, type: e.type, placeholder: (e.placeholder||'').slice(0,30), value: e.value}));
}

() => {
  const btns = Array.from(document.querySelectorAll('button'));
  const copyBtn = btns.find(b => b.textContent.trim() === '复制');
  if (copyBtn) {
    copyBtn.click();
    return 'clicked 复制';
  }
  return 'not found';
}

