input.function:
async () => {
  const btns = Array.from(document.querySelectorAll('button'));
  const copyBtn = btns.find(b => b.textContent.trim() === '复制');
  if (!copyBtn) return {found: false, reason: 'copy button not found'};
  copyBtn.click();
  const start = Date.now();
  while (Date.now() - start < 4000) {
    const el = Array.from(document.querySelectorAll('div')).find(d => d.textContent.trim() === '问题已复制到剪贴板');
    if (el) {
      const clone = el.cloneNode(true);
      clone.id = '__toast_clone_for_screenshot';
      clone.style.position = 'fixed';
      clone.style.bottom = '120px';
      clone.style.left = '50%';
      clone.style.transform = 'translateX(-50%)';
      clone.style.zIndex = '99999';
      document.body.appendChild(clone);
      return {found: true, text: el.textContent.trim()};
    }
    await new Promise(r => setTimeout(r, 50));
  }
  return {found: false, reason: 'toast not appeared within 4s'};
}

() => {
  const c = document.getElementById('__toast_clone_for_screenshot');
  if (c) { c.remove(); return 'removed'; }
  return 'not found';
}
